{
  "item_id": "PRISMA_2020_11",
  "elements": [
    {
      "element_id": "prisma_2020_11_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "The revised Cochrane Risk of Bias tool [227] was applied to randomized controlled trials... For non-randomized and observational quantitative studies, the Effective Public Health Practice Project (EPHPP) Quality Assessment Tool was used [232].",
      "reason": "Both risk-of-bias tools (RoB 2 and EPHPP) and their assignment by study design are explicitly specified."
    },
    {
      "element_id": "prisma_2020_11_e2",
      "status": "PARTIAL",
      "chunk_id": "text_11",
      "quote": "In the EPHPP tool, domains are rated as strong, moderate, or weak and a global rating is assigned based on the number of weak domains. RoB 2 classifies studies as low risk, some concerns, or high risk, depending on the highest risk level across domains.",
      "reason": "Domains are referenced (e.g., 'Selection of the reported results', blinding, dropout) but the full set of domains/items assessed by each tool is not comprehensively listed."
    },
    {
      "element_id": "prisma_2020_11_e3",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "a global rating is assigned based on the number of weak domains. RoB 2 classifies studies as low risk, some concerns, or high risk, depending on the highest risk level across domains.",
      "reason": "Overall risk-of-bias judgements are made and the rules for deriving them are reported for both tools."
    },
    {
      "element_id": "prisma_2020_11_e4",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Within the EPHPP rating scheme, we excluded the 'Study Design' section, as it was not applicable to non-RCT studies.",
      "reason": "An adaptation to the EPHPP tool (exclusion of the Study Design section) is explicitly described."
    },
    {
      "element_id": "prisma_2020_11_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No newly developed risk-of-bias tool is reported; only existing tools (RoB 2, EPHPP) were used."
    },
    {
      "element_id": "prisma_2020_11_e6",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "Risk of bias assessments were also conducted by the three authors (MB, RD, FS) and trained graduate students. Any discrepancies in ratings were discussed until consensus was reached.",
      "reason": "Number of assessors, independence (independent assessment implied by discrepancy discussion), and consensus-based disagreement resolution are reported; interrater agreement statistics (kappa values) further support this."
    },
    {
      "element_id": "prisma_2020_11_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence describes contacting study investigators to obtain or confirm risk-of-bias information."
    },
    {
      "element_id": "prisma_2020_11_e8",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No automation tools for risk-of-bias assessment are mentioned; the assessment was performed manually by reviewers."
    }
  ],
  "confidence": 92
}

{
  "item_id": "PRISMA_2020_12",
  "elements": [
    {
